arguments:
{"script":"rm -f system_logs.txt count_non_empty_lines.sh; : > system_logs.txt; for i in $(seq 1 20); do if [ $((RANDOM%4)) -eq 0 ]; then printf '\n' >> system_logs.txt; else printf 'log_%d_%d\n' "$i" "$RANDOM" >> system_logs.txt; fi; done; cat > count_non_empty_lines.sh <<'EOF'
#!/bin/sh
grep -cve '^[[:space:]]*$' system_logs.txt
EOF
chmod +x count_non_empty_lines.sh; ./count_non_empty_lines.sh"}
